ications: AS9120B/ISO 9001:2015, CSA International, IDEA, ITAR, DSCC, GIDEP, RoHS, FCC, ERAI, JEDEC-IPC, MIL-HDBK, OASIS, AS 9120, AS 6081 -> /about-us", "Vision: Enabling the Production of your Legacy Systems -> /about-us", "Mission: quality product at best price/service, reduce costs, share knowledge, long-term partnerships -> /about-us", "Independent testing entity for aerospace, defense, medical, automotive, commercial -> /", "Located near Boston''s Technology Highways -> /about-us"], "company_type": "Distributor / reseller", "makes_products": "yes", "type_evidence": "eComp is a specialty distributor and authenticator of electronic component products for the military, aerospace, medical and industrial marketplace.", "founded_year": "", "employee_count": "", "cage_code": "1R2D3", "min_order": "", "export_compliance": ["ITAR registered"], "languages": [], "social_links": ["https://www.linkedin.com/company/electronic-components-inc-dba-ecomp/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='electronic-components-inc-dba-ecomp' AND approved AND profile IS NULL;
UPDATE companies SET description='Electronic Components & Services Inc. (EC&S) has operated from Fox Lake, Wisconsin since its founding in 1978. The company began as a printed circuit board manufacturer and has remained at the same location on Industrial Drive.

EC&S fabricates single-sided, double-sided, and multilayer PCBs. It runs two production tracks: quick-turn prototypes in small quantities, and larger production orders that can be sourced domestically or offshore. The company accepts online orders for prototypes that include tooling and test, and provides customized quotes for specific material and finish requirements.

The company serves customers in competitive electronics industries, though no specific sectors are named in its public materials. Its client base includes businesses that require prototype and production PCB quantities.

